onChange.script:

#If a user selects a new tab, we should clear what was sected on the previous tab
self.custom.itemSelection = {"itemId": None, "scheduleId": None, "workOrderId": None}

return

transforms.code:
#Tabs and the tab to open on, from the asset's _runControl attribute (its own or the closest ancestor's).
#Nothing saved: all four tabs, open on Mode (the asset editor shows the same defaults).
#A default tab that is turned off: the first enabled tab. Returned together so a stale run can't leave
#new tabs with an old index; tabContent.currentTabIndex is bidirectional, so the user's tab clicks still work
allTabs = [
	{"viewParams": {"icon": "material/calendar_today", "label": "Schedule", "value": 'schedule'}, "viewPath": "kanoa/core/templates/tabs/tabWIcon"},
	{"viewParams": {"icon": "material/list_alt", "label": "Orders", "value": 'order'}, "viewPath": "kanoa/core/templates/tabs/tabWIcon"},
	{"viewParams": {"icon": "material/qr_code", "label": "Product", "value": 'product'}, "viewPath": "kanoa/core/templates/tabs/tabWIcon"},
	{"viewParams": {"icon": "material/donut_large", "label": "Mode", "value": 'mode'}, "viewPath": "kanoa/core/templates/tabs/tabWIcon"}
]

runControl = (value.get('_runControl') if value is not None else None) or {}
tabs = [tab for tab in allTabs if runControl.get(tab['viewParams']['value'], True)]

defaultTab = runControl.get('defaultTab') or 'mode'
currentTabIndex = 0
for i, tab in enumerate(tabs):
	if tab['viewParams']['value'] == defaultTab:
		currentTabIndex = i
		break

return {'tabs': tabs, 'currentTabIndex': currentTabIndex}


assetPath = value['assetPath']
security = value['security']
crud = security['userCRUD']
canCreate = False
canEdit = False
if crud is not None and security['userId'] is not None:
	if crud['isGatewayAdmin']:
		canCreate = True
		canEdit = True if assetPath else False
	elif assetPath and crud['operateAssets']['enabled']:
		#The function is granted per asset: a role on this asset or one above it (none listed: a role on no asset, so every asset)
		paths = list(crud['operateAssets']['assets'] or [])
		if len(paths) == 0 or any(assetPath == path or assetPath.startswith(path + '\\') for path in paths):
			canCreate = True
			canEdit = True

return {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}

onChange.script:

value = self.params.value
if value.has_key('assetPath') and value['assetPath']:	system.kanoa.utilities.storeAssetPath(self, value['assetPath'])

return

transforms.code:

selector = value['selectedTab']

if selector is None or selector == 'Mode': return False #system.perspective.print('selector is %s. Not showing button.'%selector)

if not value['action']['canUpdate']: return False #system.perspective.print('No permssions')

tagOEEInfo = self.view.custom.asset.tagInfo
if tagOEEInfo is None:	return False #	system.perspective.print('No tag info')

if value['itemSelection'] is None: return False # system.perspective.print('No item selection')

if selector == 'Product':
	if value['itemSelection']['itemId'] is None: return False # 	system.perspective.print('No item selected')
	if tagOEEInfo['itemId'] == value['itemSelection']['itemId']: return False # system.perspective.print('Item already selected')

if selector == 'Orders':
	if value['itemSelection']['workOrderId'] is None: return False # 	system.perspective.print('No order selected')

	workOrderName = system.kanoa.utilities.getFieldValue('workOrderName', system.kanoa.order.getProductionOrders({'workOrderId': value['itemSelection']['workOrderId'], 'ignoreActualQty': True}))
	if workOrderName is None or tagOEEInfo['workOrderName'] == workOrderName: return False # system.perspective.print('Order is already selected')

if selector == 'Schedule':

	if value['itemSelection']['scheduleId'] is None: return False # system.perspective.print('No schedule selected')

	scheduleBlockId = system.kanoa.utilities.getFieldValue('scheduleBlockId', system.kanoa.schedule.getScheduleBlocks({'scheduleBlockId': value['itemSelection']['scheduleId']}))
	if scheduleBlockId is None: return False # system.perspective.print('schedule block not found')
	if  tagOEEInfo['modeName'] == 'Production' and tagOEEInfo['scheduleBlockId'] == scheduleBlockId: 
		system.perspective.print("Already in this schedule")
		return False # system.perspective.print('Schedule is already running')


return True
